"""WASM safeguards reject unacknowledged API drift and oversize payloads; pin checks warn."""
import base64
import contextlib
import io
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch

import check_quiddity_pin as pins
import check_wasm_api as api
import wasm_size

API = '''/* tslint:disable */
/** Generated by wasm-bindgen 1.2.3 */
export class Engine {
  free(): void;
  constructor(name: string, bytes: Uint8Array);
  apply(ops: string, commit: boolean): string;
}
export interface InitOutput {
  readonly memory: WebAssembly.Memory;
  readonly engine_free: (a: number, b: number) => void;
}
export type InitInput = RequestInfo | URL | Response;
export default function init(input?: { module_or_path: InitInput | Promise<InitInput> }): Promise<InitOutput>;
'''
CHANGELOG = '# Changelog\n\n## Unreleased\n\n### Added\n\n- Existing item.\n\n## 1.0\n\n### WASM API\n\n- Old release note.\n'
SHA = 'f5ddb726783f2e9384a55164eb7e36a1ec9a6f7c'


def manifest(kind='tag', value='v0.1.0-alpha.4'):
    return '[dependencies]\n' + '\n'.join(
        f'{name} = {{ git = "https://github.com/pzfreo/quiddity", {kind} = "{value}" }}'
        for name in ('haecceity', 'quiddity'))


def invoke(module, args):
    output = io.StringIO()
    with patch.object(sys, 'argv', [module.__file__, *args]), contextlib.redirect_stdout(output), contextlib.redirect_stderr(output):
        status = module.main()
    return status, output.getvalue()


class WasmApi(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.snapshot = self.root / api.SNAPSHOT
        self.snapshot.parent.mkdir(parents=True)
        self.snapshot.write_text(api.normalize(API))
        self.generated = self.root / api.GENERATED
        self.generated.parent.mkdir()
        self.generated.write_text(API)
        self.changelog = self.root / 'CHANGELOG.md'
        self.changelog.write_text(CHANGELOG)
        self.git('init', '-q')
        self.git('config', 'user.name', 'Test')
        self.git('config', 'user.email', 'test@example.com')
        self.git('add', '.')
        self.git('commit', '-qm', 'baseline')
        self.root_patch = patch.object(api, 'ROOT', self.root)
        self.root_patch.start()
        self.addCleanup(self.root_patch.stop)

    def git(self, *args):
        return subprocess.check_output(['git', *args], cwd=self.root, stderr=subprocess.STDOUT, text=True)

    def note(self):
        self.changelog.write_text(CHANGELOG.replace('### Added', '### WASM API\n\n- Add featureCount().\n\n### Added'))

    def drift(self):
        self.generated.write_text(API.replace('free(): void;', 'free(): void;\n  featureCount(): number;'))

    def test_snapshot_and_noise_pass(self):
        self.assertEqual(invoke(api, [])[0], 0)
        self.generated.write_text(API.replace('1.2.3', '99.0.0').replace(
            '  free(): void;\n', '').replace('  apply(', '  free(): void;\n  apply('))
        self.assertEqual(invoke(api, [])[0], 0)
        self.assertEqual(api.normalize(api.normalize(API)), api.normalize(API))

    def test_drift_requires_new_note_in_unreleased_wasm_api(self):
        self.drift()
        status, output = invoke(api, [])
        self.assertEqual(status, 1)
        self.assertIn('--update', output)
        self.changelog.write_text(CHANGELOG.replace('Existing item.', 'Add featureCount().'))
        self.assertEqual(invoke(api, [])[0], 1)
        self.note()
        self.assertEqual(invoke(api, [])[0], 0)

    def test_update_cannot_bypass_changelog_and_old_note_cannot_approve(self):
        self.note()
        self.git('add', 'CHANGELOG.md')
        self.git('commit', '-qm', 'old API note')
        self.drift()
        self.assertEqual(invoke(api, ['--update'])[0], 0)
        self.assertEqual(self.snapshot.read_text(), api.normalize(self.generated.read_text()))
        self.assertEqual(invoke(api, [])[0], 1)
        self.changelog.write_text(self.changelog.read_text().replace('Add featureCount().', 'Add featureCount() and render().'))
        self.assertEqual(invoke(api, [])[0], 0)

    def test_plain_note_and_wrapped_bullet_lines_are_accepted(self):
        self.drift()
        self.changelog.write_text(CHANGELOG.replace(
            '### Added', '### WASM API\n\nAPI change: add featureCount().\n\n### Added'))
        self.assertEqual(invoke(api, [])[0], 0)
        self.note()
        self.git('add', 'CHANGELOG.md')
        self.git('commit', '-qm', 'existing API note')
        self.assertEqual(invoke(api, [])[0], 1)
        self.changelog.write_text(self.changelog.read_text().replace(
            '- Add featureCount().', '- Add featureCount().\n  Its return value is a number.'))
        self.assertEqual(invoke(api, [])[0], 0)

    def test_explicit_base_checks_committed_snapshot_changes(self):
        base = self.git('rev-parse', 'HEAD').strip()
        self.drift()
        invoke(api, ['--update'])
        self.git('add', '.')
        self.git('commit', '-qm', 'API change without note')
        self.assertEqual(invoke(api, ['--base-ref', base])[0], 1)
        self.note()
        self.assertEqual(invoke(api, ['--base-ref', base])[0], 0)
        self.assertEqual(invoke(api, ['--base-ref', 'missing-base'])[0], 1)

    def test_literals_and_nested_types_are_preserved(self):
        source = 'export type URLValue = "https://example.com/*literal*/";\n'
        self.assertIn('"https://example.com/*literal*/"', api.normalize(source))
        self.assertIn('module_or_path: InitInput | Promise<InitInput>', api.normalize(API))
        self.assertNotIn('Generated', api.normalize(API))


class WasmSize(unittest.TestCase):
    def test_ceiling_boundary_and_headroom(self):
        with tempfile.TemporaryDirectory() as tmp:
            wasm, budget = Path(tmp) / 'test.wasm', Path(tmp) / 'budget.json'
            wasm.write_bytes(b'\0' * 100)
            for limit, expected in ((100, 0), (101, 0), (99, 1)):
                budget.write_text(json.dumps({'ceiling_bytes': limit}))
                status, output = invoke(wasm_size, [str(wasm), '--budget', str(budget)])
                self.assertEqual(status, expected, output)
                self.assertIn('headroom:', output)
                self.assertIn('gzip:', output)
            budget.write_text('{}')
            self.assertEqual(invoke(wasm_size, [str(wasm), '--budget', str(budget)])[0], 1)


class KernelPins(unittest.TestCase):
    def setUp(self):
        pins.resolve_pin.cache_clear()
        self.addCleanup(pins.resolve_pin.cache_clear)

    def test_latest_includes_prereleases_and_ignores_drafts(self):
        releases = [
            {'tag_name': 'v1', 'draft': False, 'published_at': '2026-01-01'},
            {'tag_name': 'v2-alpha', 'draft': False, 'prerelease': True, 'published_at': '2026-10-16'},
            {'tag_name': 'v3', 'draft': True, 'published_at': '2026-10-17'},
        ]
        with patch.object(pins, 'github_json', return_value=releases):
            self.assertEqual(pins.latest_release('owner/repo'), 'v2-alpha')

    def test_unsigned_in_gh_falls_back_to_public_api(self):
        response = io.StringIO('{"public": true}')
        with patch.object(pins.shutil, 'which', return_value='/bin/gh'), \
                patch.object(pins.subprocess, 'check_output', side_effect=subprocess.CalledProcessError(1, 'gh')), \
                patch.object(pins.urllib.request, 'urlopen', return_value=response) as request, \
                patch.dict(pins.os.environ, {'GITHUB_TOKEN': 'test-token'}):
            self.assertEqual(pins.github_json('repos/owner/repo'), {'public': True})
        self.assertEqual(request.call_args.args[0].get_header('Authorization'), 'Bearer test-token')

    def test_latest_release_pagination(self):
        first = [{'tag_name': 'older', 'draft': False, 'published_at': '2026-01-01'}] * 100
        second = [{'tag_name': 'newer', 'draft': False, 'published_at': '2026-10-16'}]
        with patch.object(pins, 'github_json', side_effect=[first, second]) as request:
            self.assertEqual(pins.latest_release('owner/repo'), 'newer')
        self.assertIn('page=2', request.call_args.args[0])

    def run_pin_check(self, sibling, release=False, edit_error=None):
        def github(path):
            if '/releases?' in path:
                return [{'tag_name': 'v0.1.0-alpha.4', 'draft': False, 'published_at': '2026-10-16'}]
            if '/contents/' in path:
                return {'content': base64.b64encode(sibling.encode()).decode()}
            return {'sha': SHA}
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'Cargo.toml'
            path.write_text(manifest())
            with patch.object(pins, 'github_json', side_effect=github), patch.object(pins, 'append_release_note', side_effect=edit_error) as append:
                result = invoke(pins, ['--manifest', str(path), *(['--release', 'v-test'] if release else [])])
                return result, append.call_args

    def test_equivalent_tag_and_rev_match(self):
        (status, output), append = self.run_pin_check(manifest('rev', SHA), release=True)
        self.assertEqual(status, 0)
        self.assertIn('pins match', output)
        self.assertIn(SHA, output)
        self.assertIsNone(append)

    def test_mismatch_warns_and_edits_release_only_when_requested(self):
        for release in (False, True):
            (status, output), append = self.run_pin_check(manifest('rev', 'a' * 40), release)
            self.assertEqual(status, 0)
            self.assertIn('::warning::Kernel note:', output)
            self.assertIn('tag v0.1.0-alpha.4', output)
            self.assertIn('rev ' + 'a' * 40, output)
            self.assertEqual(append is not None, release)

    def test_internal_disagreement_warns(self):
        sibling = manifest('rev', SHA).replace(f'haecceity = {{ git = "https://github.com/pzfreo/quiddity", rev = "{SHA}"',
                                               'haecceity = { git = "https://github.com/pzfreo/quiddity", rev = "' + 'b' * 40 + '"')
        (status, output), _ = self.run_pin_check(sibling)
        self.assertEqual(status, 0)
        self.assertIn('::warning::', output)

    def test_network_or_release_edit_failure_is_warning_only(self):
        with patch.object(pins, 'latest_release', side_effect=OSError('offline')):
            status, output = invoke(pins, [])
        self.assertEqual(status, 0)
        self.assertIn('::warning::', output)
        (status, output), _ = self.run_pin_check(manifest('rev', 'a' * 40), release=True,
                                              edit_error=OSError('edit denied'))
        self.assertEqual(status, 0)
        self.assertIn('Could not complete quiddity pin check: edit denied', output)

    def test_release_body_preserves_notes_and_replaces_own_line(self):
        bodies = []
        def edit(args, **kwargs):
            bodies.append(Path(args[-1]).read_text())
        with patch.object(pins.subprocess, 'check_output', return_value='Original notes\n\nKernel note: old\n'), patch.object(pins.subprocess, 'run', side_effect=edit):
            pins.append_release_note('owner/repo', 'v-test', 'Kernel note: new')
        self.assertEqual(bodies, ['Original notes\n\nKernel note: new\n'])

    def test_workspace_and_rev_pins(self):
        source = manifest('rev', SHA).replace('[dependencies]', '[workspace.dependencies]')
        source += '\n[dependencies]\nhaecceity = {workspace = true}\nquiddity = {workspace = true}\n'
        self.assertEqual(pins.kernel_pins(source), pins.kernel_pins(manifest('rev', SHA)))
        with self.assertRaises(ValueError):
            pins.kernel_pins(manifest().replace('tag =', 'branch ='))

    def test_crates_io_pins_name_their_release_tag(self):
        source = ('[dependencies]\nhaecceity = "=0.4.9"\n'
                  'quiddity = { version = "=0.4.9", default-features = false, features = ["presentation"] }\n')
        expected = ("https://github.com/pzfreo/quiddity", "tag", "v0.4.9")
        self.assertEqual(pins.kernel_pins(source), {"haecceity": expected, "quiddity": expected})
        for loose in ('"0.4.9"', '"^0.4"', '{ version = ">=0.4.9" }'):
            with self.assertRaises(ValueError):
                pins.kernel_pins(f'[dependencies]\nhaecceity = {loose}\nquiddity = "=0.4.9"\n')


if __name__ == '__main__':
    unittest.main()
